      case 'viti.variedad_obligatoria_etiqueta': return 'Variedade *';
      case 'viti.variedades': return 'Variedades';
      case 'viti.ventana_razonable': return 'Xanela razoable';
      case 'viti.ventana_razonable_detalle': return 'Sen sinais fortes de xeada, deriva, choiva ou estrés hídrico.';
      case 'viti.version_instalada_y_publicada': return 'Versión instalada e última publicada';
      case 'viti.via_claude': return 'vía Claude';
      case 'viti.viento_racha': return '{viento} km/h · refacho {racha}';
      case 'viti.vigor_valor': return 'Vigor: {vigor}';
      case 'viti.vinedo': return 'Viña';
      case 'viti.vinedo_obligatorio_etiqueta': return 'Viña *';
      case 'viti.zona': return 'Zona';
      case 'viti.zona_norte_atlantica': return 'Norte (atlántica)';
      case 'viti.zona_sur_mediterranea': return 'Sur (mediterránea)';
      case 'viti.cifra_estado_esperado': return 'Estado esperado';
      case 'viti.cifra_proximo_hito': return 'Próximo fito';
      default: return _tEs(c);
    }
  }

}
